     "starter": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.naive_bayes import GaussianNB\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.isotonic import IsotonicRegression\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import brier_score_loss, log_loss\nX, y = make_classification(n_samples=12000, n_features=20, n_informative=6, n_redundant=10, flip_y=0.08, class_sep=0.8, random_state=0)\nXtr, Xrest, ytr, yrest = train_test_split(X, y, test_size=0.6, random_state=0)\nXcal, Xte, ycal, yte = train_test_split(Xrest, yrest, test_size=0.5, random_state=1)\nmodels = {\"logistic\": LogisticRegression(max_iter=2000), \"naive Bayes\": GaussianNB(), \"random forest\": RandomForestClassifier(200, random_state=0)}\nprobs, cal_probs = {}, {}\nfor name, m in models.items():\n    m.fit(Xtr, ytr)\n    probs[name], cal_probs[name] = m.predict_proba(Xte)[:, 1], m.predict_proba(Xcal)[:, 1]\ndef reliability(p, y, bins=10):\n    edges = np.linspace(0, 1, bins + 1)\n    idx = np.clip(np.digitize(p, edges) - 1, 0, bins - 1)\n    return [(round(float(p[idx == b].mean()), 2), round(float(y[idx == b].mean()), 2), int((idx == b).sum())) for b in range(bins) if (idx == b).sum() > 0]\ndef ece(p, y, bins=10):\n    edges = np.linspace(0, 1, bins + 1)\n    idx = np.clip(np.digitize(p, edges) - 1, 0, bins - 1)\n    return float(sum((idx == b).mean() * abs(p[idx == b].mean() - y[idx == b].mean()) for b in range(bins) if (idx == b).sum() > 0))"
